with d as (select value r from jsonb_array_elements($q$[{"notes":["Keep in the fridge for up to 3 days and serve cold, or reheat gently in a 180°C oven.","No chilli in the house? Use a pinch of dried oregano instead, or just the onions. The frittata doesn't need much.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"id":"786df343-cd47-4248-a178-7e5a1a725dd2"},{"notes":["Make it ahead: cook it the day before, cool quickly, and refrigerate in an airtight container for up to 3 days. Reheat gently in the pot with a splash of water.","This is Jamaican rice and peas, which uses kidney beans, not the peas you might find elsewhere in the Caribbean."],"steps":[{"text":"Pour the coconut milk into a large measuring jug and add water to make 600 ml total. Stir well to combine."},{"text":"Heat the oil in a heavy-bottomed pot over medium heat. Add the onion and cook, stirring, until softened and fragrant, about 3 minutes."},{"text":"Add the garlic and cook, stirring, for 1 minute more."},{"text":"Add the rice, stirring to coat in the oil, about 1 minute."},{"text":"Pour in the coconut milk mixture and stock, then add the kidney beans, thyme, salt and pepper. Stir well and bring to a boil until the liquid is bubbling steadily."},{"text":"Once boiling, reduce the heat to low, cover with a tight-fitting lid, and cook for 18 to 20 minutes, until the rice is tender and the liquid is absorbed. Do not lift the lid during cooking."},{"text":"Remove from the heat and let it rest, covered, for 2 minutes. Fluff with a fork, discard the thyme sprig if using fresh, and scatter with spring onion if you like."}],"id":"53b7958d-9eb9-43ae-b589-d853f67e777e"},{"diets":["pescatarian","no-gluten","no-dairy"],"notes":["Use good-quality fresh tuna; frozen won't give you the same result.","Don't stir too much once the tuna is in, you want to keep the chunks intact.","Food safety: Cook fish until it is opaque and flakes easily (63°C in the thickest part), and prawns until pink and opaque all the way through."],"id":"764dbee9-eb81-4b2f-b23f-847c0701a0a0"},{"notes":["If you can't find millet, substitute with 150 g of pearl barley or extra rice, though the texture won't be quite the same.","Make it the night before and reheat gently with a splash of water, the flavour deepens overnight.","The best toppings are fried plantain, avocado slices, grated hard-boiled egg, and a spoonful of hot shito (pepper) sauce on the side."],"id":"14745b20-58d7-4f75-943a-561053a418cf"},{"notes":["The horseradish cream can be made up to 2 hours ahead and kept in the fridge.","Use the best smoked mackerel you can get, local fishmonger quality makes all the difference."],"id":"f3e06db8-1730-4aea-811d-4bec191708cd"},{"notes":["Make it the day before and refrigerate, it actually improves. Just add 10 minutes to the baking time if cooking from cold.","Lamb neck fillet works just as well as shoulder and gives you more flavour for the gravy.","Don't skip the second blast at high heat, that's what gets the potatoes crispy.","Food safety: Slow-cooked meat is safe once it is tender and the centre has reached at least 75°C."],"steps":[{"text":"Heat oven to 160°C. Layer half the potatoes in the bottom of a deep baking dish or casserole (about 2 litre capacity), then half the onions."},{"text":"Add all the lamb pieces, then layer the remaining onions and remaining potatoes on top, seasoning each layer with salt, pepper and thyme as you go."},{"text":"Warm the chicken stock and pour it over everything, it should come about three-quarters of the way up the dish. Dot the top with small pieces of butter."},{"text":"Cover tightly with foil and bake for 2 hours at 160°C, until the lamb is completely tender."},{"text":"Increase oven to 200°C, remove the foil, and bake uncovered for a further 15 minutes until the potato tops are golden and crispy."},{"text":"Rest for 5 minutes before serving. The gravy should come from the lamb and stock, you don't need to make it separately."}],"id":"2bc19133-3661-48e8-9436-ba8f4b38f66a"},{"notes":["Serve with torn bread to soak up the sauce.","Make the sauce ahead and reheat gently before poaching the eggs.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"id":"2e8638db-c3f2-4b0b-ae97-f6eb1371a058"},{"notes":["Make this salad just before eating, if it sits too long, the vegetables release water and it becomes watery.","The dice should be fine and even. This isn't just cutting vegetables small; it's about texture, so every piece sits together in the bowl."],"steps":[{"text":"Dice the tomatoes into small, even pieces about the size of a pea, working over a bowl to catch the juice."},{"text":"Dice the cucumber to the same size as the tomato."},{"text":"Finely chop the parsley, removing the coarse stems and using mostly the leaves."},{"text":"Combine the tomato, cucumber and parsley in a bowl."},{"text":"Pour the lemon juice and olive oil over the vegetables and toss gently but thoroughly so everything is well coated."},{"text":"Taste and add salt until it's right, not too much, just enough to bring out the flavour of the vegetables."},{"text":"Serve straight away with warm bread to eat it with."}],"id":"af161dce-3949-4e13-b2bf-13c1ec905c57"},{"notes":["Thieboudienne can be made a day ahead: cook the fish and vegetables up to step 5, cool and refrigerate, then finish the rice and reheat gently before serving.","If you can't find a whole fish, use thick fish steaks (about 200g each) and add them after the rice has cooked for 15 minutes, so they don't break up.","The caramelized onion base is everything, don't rush it. The darker and deeper the onions, the better the dish.","Food safety: Cook fish until it is opaque and flakes easily (63°C in the thickest part), and prawns until pink and opaque all the way through."],"id":"9a9feab9-a598-4b10-a9aa-dbdf04e56cdc"},{"notes":["The chicken liver must not be overcooked or it becomes tough. Add it back to the pot at the very end.","Fresh egg noodles cook much faster than dried; if using dried noodles, add them earlier and cook for 8–10 minutes.","The cornflour slurry must be stirred in slowly to avoid lumps.","Food safety: Cook chicken and other poultry until the juices run clear and the thickest part reaches 75°C."],"id":"a6da6d2f-7381-4472-ac8f-f771d5904d72"},{"notes":["Beef ribs (short ribs or beef back ribs) cook beautifully the same way, just allow an extra 2–3 minutes per side.","No grill? A heavy cast-iron pan on the stove over high heat works. You won't get the same char, but the flavour will be there.","Best eaten straight off the heat with your flatmates and cold beers.","Food safety: Cook whole cuts of beef, lamb and pork to at least 63°C in the thickest part, then rest for 3 minutes; cook pork and any rolled or stuffed cuts until the juices run clear."],"steps":[{"text":"Heat your grill or barbecue to hot. If using charcoal, wait until the coals are white and glowing; if gas, get it smoking."},{"text":"Pat the beef dry with paper towel until the surface is no longer wet. This helps it char, not steam."},{"text":"Rub the meat lightly with oil, then season generously with salt on both sides."},{"text":"Lay the meat on the grill in a single layer. Don't move it for the first 4 minutes, you want a good char."},{"text":"Flip and cook the other side for another 4 minutes. The meat should have a dark crust but still be pink inside (about 55°C on a meat thermometer)."},{"text":"Transfer to a warm plate. Squeeze lime over the hot meat, it'll sizzle and the juice will run into all the crevices."},{"text":"Let it rest for 2 minutes, then serve with extra lime wedges and salt on the side for dipping."}],"id":"c0279693-c922-4670-8c65-1ad83d1abc92"},{"notes":["Use a rotisserie chicken from Coles if you don't have cooked chicken on hand, shred the meat, skip the skin.","Salsa verde comes in jars in most supermarkets (Coles has it). If you can't find it, blend canned green tomatoes (tomatillos) with a jalapeño, coriander, and lime juice.","Make ahead: assemble the dish, cover with foil, and refrigerate up to 24 hours. Bake for an extra 5 minutes if cooking from cold.","Cook chicken until it reaches 75°C in the thickest part and the juices run clear."],"id":"3f192f3c-8e9b-4c06-a4c8-07deb77c97ad"},{"notes":["Make the filling and dough a day ahead; chill separately. Roll and fold the morning of, then chill on the tray.","Freeze uncooked tortellini on a tray, then transfer to a freezer bag. Cook from frozen, adding 1–2 minutes to the simmer time.","The filling should taste bold, it seasons the broth. Don't be shy with salt, pepper, and nutmeg.","Cook chicken until it reaches 75°C in the thickest part and the juices run clear.","Food safety: Cook mince, sausages, meatballs and liver right through to 75°C, with no pink in the centre."],"steps":[{"text":"Make the pasta: mound flour on a bench, crack eggs into centre, add a pinch of salt. Work with a fork until shaggy, then knead by hand for 8–10 minutes until smooth and elastic. Wrap and rest 30 minutes."},{"text":"Make the filling: fry pork mince in a pan over medium heat, breaking it up, until it loses its colour, about 5 minutes. Cool completely, then mix with ham, parmesan, breadcrumbs, egg yolk, nutmeg, salt and pepper. Taste and adjust."},{"text":"Roll the pasta: divide dough into 4 pieces. Working with one at a time (keep others covered), roll very thin on a lightly floured surface, thin enough to read through. Using a 5 cm cutter or glass, cut circles."},{"text":"Fill and fold: place ½ tsp filling slightly off-centre on each circle. Fold in half to make a half-moon, press edges firmly. Bring the two points of the half-moon together to seal into a ring. Place on a tray lined with baking paper, well spaced. Repeat until done."},{"text":"Chill the tortellini on the tray, uncovered, for at least 30 minutes (or up to 4 hours before cooking)."},{"text":"Bring stock to a steady simmer in a large pot. Carefully drop in tortellini, a few at a time so the broth stays moving. They'll sink, then float to the surface; simmer for 2–3 minutes after they float."},{"text":"Serve in bowls with hot broth, grated parmesan, a crack of black pepper, and parsley if you like."}],"id":"7dbd2c96-e4b8-45bb-9540-b8fff11e379a"},{"notes":["Beef tongue keeps well raw for 2 days in the fridge, wrapped. Ask your butcher to slice it thin on the deli slicer, or freeze for an hour and slice yourself with a sharp knife.","Cooked tongue is best eaten fresh, but any leftovers are good cold the next day.","Food safety: Steaks and roasting cuts of beef or lamb can be served pink: about 60°C in the centre is medium-rare, 70°C is well done."],"id":"32cfe5a3-cafb-49fa-af7a-95728bef5eb2"},{"notes":["If you can't find fresh tamarind paste, use 1½ tbsp tamarind concentrate or 2 tbsp lime juice for a lighter sour note.","The herbs are not optional, they're what makes it sing. Vietnamese mint (laksa leaf) is traditional, but use whatever fresh herbs you have.","Food safety: Cook fish until it turns opaque and flakes easily, about 63°C in the thickest part."],"id":"dda55326-2dd1-4129-a4d8-2336a3397614"}]$q$::jsonb)), up as (update public.published_recipes p set recipe = p.recipe || (d.r - 'id' - 'notes') || case when d.r ? 'notes' then jsonb_build_object('notes', coalesce((select jsonb_agg(n) from jsonb_array_elements(d.r->'notes') n where btrim(n#>>'{}') <> 'Food safety:'),'[]'::jsonb)) else '{}'::jsonb end, diets = case when d.r ? 'diets' then array(select jsonb_array_elements_text(d.r->'diets')) else p.diets end from d where p.id=(d.r->>'id')::uuid returning p.id) select (select count(*) from d) expected, (select count(*) from up) updated;